تصميم محرك Analytics مجمع مع طابور تخزين محلي وتطهير البيانات الحساسة:
```kotlin
class AnalyticsEventDispatcher @Inject constructor(
    private val eventQueueDao: AnalyticsDao,
    private val analyticsApi: AnalyticsApiService
) {
    private val eventChannel = Channel<AnalyticsEvent>(Channel.BUFFERED)
    private val BATCH_SIZE = 25

    init {
        startBatchProcessor()
    }

    fun trackEvent(name: String, params: Map<String, Any> = emptyMap()) {
        // 1. تطهير البيانات وحجب أي حقول حساسة:
        val sanitizedParams = params.filterKeys { !it.contains("password", true) && !it.contains("card", true) }
        val event = AnalyticsEvent(name = name, parameters = sanitizedParams, timestamp = System.currentTimeMillis())
        eventChannel.trySend(event)
    }

    private fun startBatchProcessor() {
        CoroutineScope(Dispatchers.IO).launch {
            val buffer = mutableListOf<AnalyticsEvent>()
            while (isActive) {
                // 2. تجميع الأحداث حتى اكتمال الـ Batch أو انقضاء مهلة زمنية
                val event = withTimeoutOrNull(30_000L) { eventChannel.receive() }
                if (event != null) buffer.add(event)

                if (buffer.size >= BATCH_SIZE || (buffer.isNotEmpty() && event == null)) {
                    try {
                        analyticsApi.sendBatch(buffer.toList())
                        buffer.clear()
                    } catch (e: Exception) {
                        // في حال فشل الشبكة: حفظ الأحداث في قاعدة البيانات المحلية لإرسالها لاحقاً
                        eventQueueDao.insertAll(buffer.map { it.toEntity() })
                        buffer.clear()
                    }
                }
            }
        }
    }
}
```

تنفيذ State Machine صريحة ونقية مع MVI لتدفق دفع معقد ومنع الحالات المتضاربة:
```kotlin
// 1. نمذجة الحالات الممكنة حصرياً (Impossible States are Unrepresentable):
sealed interface CheckoutState {
    object Idle : CheckoutState
    object ProcessingPayment : CheckoutState
    data class AwaitingOtpVerification(val transactionId: String) : CheckoutState
    data class Completed(val receiptNumber: String) : CheckoutState
    data class Failed(val reason: String, val canRetry: Boolean) : CheckoutState
}

// 2. نمذجة الأحداث الصريحة:
sealed interface CheckoutEvent {
    data class SubmitPayment(val cardToken: String) : CheckoutEvent
    data class VerifyOtp(val code: String) : CheckoutEvent
    object Retry : CheckoutEvent
}

// 3. محرك الـ State Machine داخل ViewModel:
class CheckoutStateMachineViewModel @Inject constructor(
    private val paymentRepository: PaymentRepository
) : ViewModel() {
    private val _state = MutableStateFlow<CheckoutState>(CheckoutState.Idle)
    val state: StateFlow<CheckoutState> = _state.asStateFlow()

    fun onEvent(event: CheckoutEvent) {
        val currentState = _state.value
        viewModelScope.launch {
            when (event) {
                is CheckoutEvent.SubmitPayment -> {
                    if (currentState is CheckoutState.Idle || currentState is CheckoutState.Failed) {
                        _state.value = CheckoutState.ProcessingPayment
                        val result = paymentRepository.process(event.cardToken)
                        _state.value = when (result) {
                            is PaymentResult.RequiresOtp -> CheckoutState.AwaitingOtpVerification(result.txId)
                            is PaymentResult.Success -> CheckoutState.Completed(result.receipt)
                            is PaymentResult.Error -> CheckoutState.Failed(result.message, canRetry = true)
                        }
                    }
                }
                is CheckoutEvent.VerifyOtp -> {
                    if (currentState is CheckoutState.AwaitingOtpVerification) {
                        _state.value = CheckoutState.ProcessingPayment
                        // تنفيذ التحقق وتحديث الحالة
                    }
                }
                is CheckoutEvent.Retry -> {
                    if (currentState is CheckoutState.Failed && currentState.canRetry) {
                        _state.value = CheckoutState.Idle
                    }
                }
            }
        }
    }
}
```

تنفيذ دالة تنفيذ شبكي مرنة ومقاومة للأخطاء مع Exponential Backoff و Jitter ومعالجة الـ Idempotency:
```kotlin
suspend fun <T> executeWithRetry(
    maxRetries: Int = 3,
    baseDelayMs: Long = 1000L,
    maxDelayMs: Long = 10000L,
    block: suspend () -> T
): Result<T> {
    var currentAttempt = 0
    while (currentAttempt < maxRetries) {
        try {
            return Result.success(block())
        } catch (e: IOException) {
            currentAttempt++
            if (currentAttempt >= maxRetries) return Result.failure(e)

            // حساب Exponential Backoff مع Full Jitter لمنع الـ Thundering Herd:
            val exponential = (baseDelayMs * (1 shl (currentAttempt - 1))).coerceAtMost(maxDelayMs)
            val jitter = Random.nextLong(0, exponential)
            delay(jitter)
        } catch (e: Exception) {
            // الأخطاء غير القابلة للتعافي (مثل 400 Bad Request أو 403 Forbidden) لا يُعاد محاولتها
            return Result.failure(e)
        }
    }
    return Result.failure(IllegalStateException("Exhausted retries"))
}
```

